// Dynamic Role Category Badge Configuration
function getDashboardRoleBadge(role, dept) {
    const text = ((role || '') + ' ' + (dept || '')).toLowerCase();
    if (text.includes('account') || text.includes('finance') || text.includes('billing')) {
        return { label: 'Accounts', bg: 'rgba(16, 185, 129, 0.16)', color: '#34d399', border: 'rgba(16, 185, 129, 0.4)', icon: 'credit-card' };
    }
    if (text.includes('sale') || text.includes('crm')) {
        return { label: 'Sales', bg: 'rgba(245, 158, 11, 0.16)', color: '#fbbf24', border: 'rgba(245, 158, 11, 0.4)', icon: 'trending-up' };
    }
    if (text.includes('cad') || text.includes('design') || text.includes('drawing')) {
        return { label: 'Drawing', bg: 'rgba(56, 189, 248, 0.16)', color: '#38bdf8', border: 'rgba(56, 189, 248, 0.4)', icon: 'pen-tool' };
    }
    if (text.includes('pack')) {
        return { label: 'Packing', bg: 'rgba(99, 102, 241, 0.16)', color: '#818cf8', border: 'rgba(99, 102, 241, 0.4)', icon: 'box' };
    }
    if (text.includes('deliver') || text.includes('driver') || text.includes('transit') || text.includes('logistic')) {
        return { label: 'Delivery', bg: 'rgba(244, 63, 94, 0.16)', color: '#fb7185', border: 'rgba(244, 63, 94, 0.4)', icon: 'truck' };
    }
    if (text.includes('weld') || text.includes('fab')) {
        return { label: 'Fabrication', bg: 'rgba(236, 72, 153, 0.16)', color: '#f472b6', border: 'rgba(236, 72, 153, 0.4)', icon: 'flame' };
    }
    if (text.includes('cnc') || text.includes('machin')) {
        return { label: 'CNC Machinery', bg: 'rgba(168, 85, 247, 0.16)', color: '#c084fc', border: 'rgba(168, 85, 247, 0.4)', icon: 'cpu' };
    }
    if (text.includes('sup') || text.includes('operat')) {
        return { label: 'Supervisor', bg: 'rgba(14, 165, 233, 0.16)', color: '#38bdf8', border: 'rgba(14, 165, 233, 0.4)', icon: 'shield-alert' };
    }
    return { label: 'Production', bg: 'rgba(167, 139, 250, 0.16)', color: '#c4b5fd', border: 'rgba(167, 139, 250, 0.4)', icon: 'hammer' };
}

