// Live Clock for Dashboard Top Header
function initDashboardHeaderClock() {
    function updateClock() {
        const dateEl = document.getElementById('dashboard-header-date');
        const timeEl = document.getElementById('dashboard-header-time');
        if (!dateEl || !timeEl) return;
        const now = new Date();
        const dateStr = now.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
        const timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
        dateEl.textContent = dateStr;
        timeEl.textContent = timeStr;
    }
    updateClock();
    if (window._dashClockTimer) clearInterval(window._dashClockTimer);
    window._dashClockTimer = setInterval(updateClock, 1000);
}

// Helper: KPI card with Sparkline & Clickable Report Statement Navigation
function createSparklineKpiCard(title, value, change, color, icon, sparklinePath, subtitle = '', yearlyText = '', route = '') {
    return `
        <div class="glass-panel" 
             onclick="${route ? `window.navigate('${route}')` : ''}"
             title="${route ? `Click to view ${title} Detailed Statement & Report` : ''}"
             style="
                 padding: 0.95rem 1.15rem; border-radius: var(--radius-md); display: flex; justify-content: space-between; align-items: center; 
                 position: relative; overflow: hidden; background: var(--color-bg-card); border: 1px solid var(--glass-border); 
                 cursor: ${route ? 'pointer' : 'default'}; transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
             " 
             onmouseover="this.style.transform='translateY(-3px)'; this.style.borderColor='${color}80'; this.style.boxShadow='var(--shadow-md), 0 0 16px ${color}30';" 
             onmouseout="this.style.transform='none'; this.style.borderColor='var(--glass-border)'; this.style.boxShadow='none';">
            <div style="flex: 1;">
                <div style="display: flex; align-items: center; gap: 0.45rem; margin-bottom: 0.35rem;">
                    <div style="width: 24px; height: 24px; border-radius: 6px; background: ${color}20; display: flex; align-items: center; justify-content: center; color: ${color};">
                        <i data-lucide="${icon}" style="width: 14px; height: 14px;"></i>
                    </div>
                    <span style="font-size: 0.74rem; color: var(--color-text-muted); font-weight: 600;">${title}</span>
                    <span style="font-size: 0.7rem; color: ${color}; font-weight: 700; margin-left: auto;">${change}</span>
                </div>
                <div style="font-size: 1.25rem; font-weight: 700; color: var(--color-text-heading); letter-spacing: -0.3px;">${value}</div>
                ${subtitle ? `<div style="font-size: 0.68rem; color: var(--color-text-muted); margin-top: 2px;">${subtitle}</div>` : ''}
                ${yearlyText ? `<div style="font-size: 0.72rem; color: var(--color-text-subtle); margin-top: 3px; font-weight: 500;">${yearlyText}</div>` : ''}
                ${route ? `
                    <div style="display: flex; align-items: center; gap: 3px; font-size: 0.66rem; color: ${color}; margin-top: 5px; font-weight: 600; opacity: 0.95;">
                        <span>Click for Statement</span>
                        <i data-lucide="chevron-right" style="width: 11px; height: 11px;"></i>
                    </div>
                ` : ''}
            </div>
            <div style="width: 65px; height: 32px; margin-left: 0.5rem; opacity: 0.85;">
                <svg viewBox="0 0 100 32" style="width: 100%; height: 100%; overflow: visible;">
                    <path d="${sparklinePath}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" />
                    <circle cx="100" cy="4" r="3.5" fill="${color}" />
                </svg>
            </div>
        </div>
    `;
}

// Helper: Stock Alert Mini Table Rows (Strictly 3 Columns: Product, Category, Stock)
function renderStockAlertRows(items, badgeColor) {
    const isOutOfStock = badgeColor === '#ef4444';
    return items.map(row => `
        <tr style="border-bottom: 1px solid var(--glass-border); color: var(--color-text-main); cursor: pointer; transition: background 0.15s ease;" onmouseover="this.style.background='var(--color-primary-subtle)'" onmouseout="this.style.background='transparent'" onclick="window.navigate('stock_manager')">
            <td style="padding: 0.5rem 0.45rem; font-weight: 600; font-size: 0.77rem; color: var(--color-text-heading); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${row.name}">
                ${row.name}
            </td>
            <td style="padding: 0.5rem 0.45rem; color: var(--color-text-muted); font-size: 0.72rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                <span style="background: var(--color-primary-subtle); padding: 2px 6px; border-radius: 4px; border: 1px solid var(--glass-border); color: var(--color-text-muted); font-weight: 500; display: inline-block;">
                    ${row.category || 'Hardware'}
                </span>
            </td>
            <td style="padding: 0.5rem 0.45rem; text-align: right; font-weight: 700;">
                <span style="display: inline-flex; align-items: center; justify-content: center; min-width: 24px; padding: 2px 6px; border-radius: 6px; font-weight: 700; font-size: 0.76rem; background: ${isOutOfStock ? 'rgba(239, 68, 68, 0.14)' : 'rgba(245, 158, 11, 0.14)'}; color: ${badgeColor}; border: 1px solid ${isOutOfStock ? 'rgba(239, 68, 68, 0.3)' : 'rgba(245, 158, 11, 0.3)'};">
                    ${row.stock}
                </span>
            </td>
        </tr>
    `).join('');
}

// Helper: Site Visit & Service Rows with Distinct Tag Badges
function renderSiteVisitAndServiceRows(items) {
    return items.map(item => `
        <tr style="border-bottom: 1px solid var(--glass-border); color: var(--color-text-main); cursor: pointer; transition: background 0.15s ease;" onmouseover="this.style.background='var(--color-primary-subtle)'" onmouseout="this.style.background='transparent'" onclick="window.navigate('${item.type === 'Service' ? 'service_visit' : 'site_visit'}')">
            <td style="padding: 0.55rem 0.3rem;">
                ${item.type === 'Service' 
                    ? `<span class="badge-service"><i data-lucide="wrench" style="width: 10px; height: 10px;"></i> Service</span>`
                    : `<span class="badge-site-visit"><i data-lucide="map-pin" style="width: 10px; height: 10px;"></i> Site Visit</span>`
                }
            </td>
            <td style="width: 95px; padding: 0.55rem 0.3rem; font-weight: 500; color: var(--color-text-heading);">${item.date}</td>
            <td style="width: 75px; padding: 0.55rem 0.3rem; color: var(--color-text-muted);">${item.time}</td>
            <td style="padding: 0.55rem 0.3rem; font-weight: 600; color: var(--color-text-heading);">${item.customer}</td>
            <td style="padding: 0.55rem 0.3rem; color: var(--color-text-main);">${item.loc}</td>
            <td style="padding: 0.55rem 0.3rem; color: var(--color-text-muted); font-size: 0.75rem;">${item.purpose}</td>
            <td style="width: 90px; padding: 0.55rem 0.3rem;">
                <span class="badge-status-pill ${item.status === 'Confirmed' ? 'success' : item.status === 'In Progress' ? 'warning' : item.status === 'Scheduled' ? 'info' : 'purple'}">
                    <span style="width: 5px; height: 5px; border-radius: 50%; background: currentColor; box-shadow: 0 0 5px currentColor;"></span>
                    ${item.status}
                </span>
            </td>
        </tr>
    `).join('');
}

// Helper: Quotation Pending Rows with Uniform Status Pills and Glassmorphic Styling
function renderQuotationPendingRows(items) {
    return items.map(q => `
        <tr style="border-bottom: 1px solid var(--glass-border); color: var(--color-text-main); cursor: pointer; transition: background 0.15s ease;" onmouseover="this.style.background='var(--color-primary-subtle)'" onmouseout="this.style.background='transparent'" onclick="window.navigate('quotations')">
            <td style="padding: 0.6rem 0.3rem; font-family: monospace; font-weight: 600; color: var(--color-primary);">${q.id}</td>
            <td style="padding: 0.6rem 0.3rem; font-weight: 600; color: var(--color-text-heading);">
                ${q.customer}
                <div style="font-size: 0.68rem; color: var(--color-text-muted); font-weight: 400;">${q.loc}</div>
            </td>
            <td style="padding: 0.6rem 0.3rem; color: var(--color-text-muted);">${q.date}</td>
            <td style="padding: 0.6rem 0.3rem; text-align: right; font-weight: 700; color: #10b981;">₹ ${q.amount.toLocaleString('en-IN')}</td>
            <td style="padding: 0.6rem 0.3rem; text-align: center;">
                <span class="badge-status-pill ${q.status === 'Sent' ? 'info' : q.status === 'Pending' ? 'warning' : 'purple'}">
                    <span style="width: 5px; height: 5px; border-radius: 50%; background: currentColor; box-shadow: 0 0 5px currentColor;"></span>
                    ${q.status}
                </span>
            </td>
            <td style="padding: 0.6rem 0.3rem; text-align: right;">
                <button class="btn btn-secondary" style="padding: 2px 8px; font-size: 0.7rem; background: var(--color-primary-subtle); color: var(--color-primary); border: 1px solid var(--color-primary-border); border-radius: 6px; display: inline-flex; align-items: center; gap: 3px;">
                    <i data-lucide="eye" style="width: 11px; height: 11px;"></i> Review
                </button>
            </td>
        </tr>
    `).join('');
}

