window.toggleDashboardRoleDropdown = (e) => {
    if (e) {
        e.stopPropagation();
        e.preventDefault();
    }
    const dropdown = document.getElementById('dashboardRoleDropdownPanel');
    if (!dropdown) return;
    const isVisible = dropdown.style.display === 'block';
    if (isVisible) {
        dropdown.style.display = 'none';
    } else {
        dropdown.style.display = 'block';
        setTimeout(() => {
            const searchInput = document.getElementById('dashboardRoleSearchInput');
            if (searchInput) {
                searchInput.value = '';
                searchInput.focus();
                window.filterDashboardRoleDropdown('');
            }
            if (window.lucide) window.lucide.createIcons();
        }, 15);
    }
};

window.closeDashboardRoleDropdown = () => {
    const dropdown = document.getElementById('dashboardRoleDropdownPanel');
    if (dropdown) dropdown.style.display = 'none';
};

window.filterDashboardRoleDropdown = (query) => {
    const q = (query || '').toLowerCase().trim();
    const items = document.querySelectorAll('.role-dropdown-item');
    let visibleCount = 0;
    items.forEach(item => {
        const searchKeywords = item.getAttribute('data-search') || '';
        if (!q || searchKeywords.includes(q)) {
            item.style.display = 'flex';
            visibleCount++;
        } else {
            item.style.display = 'none';
        }
    });

    const emptyState = document.getElementById('roleDropdownEmptyState');
    if (emptyState) {
        emptyState.style.display = visibleCount === 0 ? 'block' : 'none';
    }
};

window.applyDashboardRoleCategoryFilter = (cat) => {
    const searchInput = document.getElementById('dashboardRoleSearchInput');
    const pills = document.querySelectorAll('.role-cat-pill');
    pills.forEach(p => {
        if (p.getAttribute('data-cat') === cat) {
            p.style.background = 'var(--color-primary, #38bdf8)';
            p.style.color = '#000';
            p.style.fontWeight = '700';
        } else {
            p.style.background = 'rgba(255,255,255,0.03)';
            p.style.color = '#cbd5e1';
            p.style.fontWeight = '400';
        }
    });

    if (cat === 'All') {
        if (searchInput) searchInput.value = '';
        window.filterDashboardRoleDropdown('');
    } else {
        if (searchInput) searchInput.value = cat;
        window.filterDashboardRoleDropdown(cat);
    }
};

window.selectDashboardRolePerspective = (userId) => {
    window.closeDashboardRoleDropdown();
    if (typeof window.switchActiveUser === 'function') {
        window.switchActiveUser(userId);
    }
};

if (typeof document !== 'undefined' && !window._hasAttachedRoleDropdownClick) {
    window._hasAttachedRoleDropdownClick = true;
    document.addEventListener('click', (e) => {
        const wrapper = document.getElementById('dashboardRoleComboboxWrapper');
        if (wrapper && !wrapper.contains(e.target)) {
            window.closeDashboardRoleDropdown();
        }
    });
}


